class Solution {
 static const int MOD=1000000007;
 long long power(long long a,long long b){long long r=1;for(;b;b>>=1,a=a*a%MOD)if(b&1)r=r*a%MOD;return r;}
public:
 vector<int> waysToFillArray(vector<vector<int>>& queries){
  int maxN=0;for(auto& q:queries)maxN=max(maxN,q[0]+15);
  vector<long long> fact(maxN+1,1),inv(maxN+1,1);
  for(int i=1;i<=maxN;++i)fact[i]=fact[i-1]*i%MOD;
  inv[maxN]=power(fact[maxN],MOD-2);
  for(int i=maxN;i>0;--i)inv[i-1]=inv[i]*i%MOD;
  auto choose=[&](int n,int r)->long long{return fact[n]*inv[r]%MOD*inv[n-r]%MOD;};
  vector<int> ans;
  for(auto& q:queries){int n=q[0],k=q[1];long long ways=1;
   for(int p=2;p*p<=k;++p)if(k%p==0){int e=0;while(k%p==0){k/=p;++e;}ways=ways*choose(n+e-1,e)%MOD;}
   if(k>1)ways=ways*n%MOD;
   ans.push_back(ways);
  }return ans;
 }
};
